const webhookData = $("Google Fit Sync Webhook").first().json.body || {};
const userId = webhookData.user_id || 4;
const stepCount = webhookData.step_count !== undefined ? webhookData.step_count : Math.floor(Math.random() * 4000) + 4000;
const heartRate = webhookData.heart_rate !== undefined ? webhookData.heart_rate : Math.floor(Math.random() * 25) + 65;
const timestamp = new Date().toISOString();

return [{
  json: {
    user_id: userId,
    step_count: stepCount,
    distance_meters: stepCount * 0.75,
    calories: stepCount * 0.04,
    heart_rate: heartRate,
    device_id: 'google_fit_watch_v2',
    sync_source: 'Google Fit REST API v1',
    timestamp: timestamp
  }
}];

const item = $("Simulate Google Fit Telemetry").first().json;
return [{
  json: {
    workflow: 'Workflow 4: Google Fit Sync',
    status: 'SUCCESS',
    execution_confirmed: true,
    user_id: item.user_id,
    step_count: item.step_count,
    synced_at: new Date().toISOString(),
    details: item
  }
}];
